void Importance_Resample (long nSims, long *pIndex0, long *pIndex1,
                          long *plDrawn, double *pdL, double dSumL)
{
  long i, j;
  for (i = 0; i < nSims; i++)
    pdL[i] = pdL[i] / dSumL;
  j = 0;
  do {
    i = (long) floor (Randoms() * nSims);
    if (Randoms() < pdL[i]) {
      pIndex1[j] = pIndex0[i];
      j++;
      plDrawn[pIndex0[i]]++;
    }
  }
  while (j < nSims);
}

