int
xmlSerializeDecCharRef(char *buf, int val) {
    char *out = buf;
    int len, i;
    *out++ = '&';
    *out++ = '#';
    if (val < 100) {
        len = (val < 10) ? 1 : 2;
    } else if (val < 10000) {
        len = (val < 1000) ? 3 : 4;
    } else if (val < 1000000) {
        len = (val < 100000) ? 5 : 6;
    } else {
        len = 7;
    }
    for (i = len - 1; i >= 0; i--) {
        out[i] = '0' + val % 10;
        val /= 10;
    }
    out[len] = ';';
    return(len + 3);
}

