  long i, j;
  for (i = 0; i < nSims; i++)
    pdL[i] = pdL[i] / dSumL;
  j = 0;
  do {
    i = (long) floor (Randoms() * nSims);
    if (Randoms() < pdL[i]) {
      pIndex1[j] = pIndex0[i];
      j++;
      plDrawn[pIndex0[i]]++;
