                   long istart, long ifinish)
{
  long i, j;
  register double ave, ss, dTmp;
  ss = 0;
  for (i = istart; i < ifinish; i++) {
    ave = 0;
    for (j = 0; j < nDim; j++) {
      ave = ave + pdIR[j] * log(pdX[j][i]);
    }
    for (j = 0; j < nDim; j++) {
      dTmp = log(pdX[j][i]) - ave;
      ss = ss + pdIR[j] * dTmp * dTmp;
    }
  }
  return (ss / (double) (ifinish - istart));
}

